-- Reviewed senior batch 029; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":862,"word":"entity","meaning":"實體","example":"The museum became a separate entity after the reorganization.","example_zh":"改組後，博物館成為獨立實體。","original_meaning":"實體","original_example":"A legal entity.","original_example_zh":"一個法律實體。"},{"source_id":864,"word":"envision","meaning":"預想","example":"The students tried to envision a greener school.","example_zh":"學生試著想像更綠化的校園。","original_meaning":"預想","original_example":"Envision a better future.","original_example_zh":"展望更美好的未來。"},{"source_id":865,"word":"equity","meaning":"公平","example":"The committee considered equity when distributing the resources.","example_zh":"委員會分配資源時考量公平。","original_meaning":"公平","original_example":"They used their home equity to fund their children's college education.","original_example_zh":"他們利用房屋淨值來資助子女的大學教育。"},{"source_id":866,"word":"erratic","meaning":"不穩定的","example":"The toy car's erratic movement made it hard to follow.","example_zh":"玩具車不穩定的移動讓人難以追蹤。","original_meaning":"不穩定的","original_example":"Erratic behavior.","original_example_zh":"反常的行為。"},{"source_id":870,"word":"evade","meaning":"逃避","example":"The speaker tried to evade the difficult question.","example_zh":"演講者試圖迴避這個困難問題。","original_meaning":"逃避","original_example":"He evaded his opponent's blows.","original_example_zh":"他閃避了對手的攻擊。"},{"source_id":872,"word":"excerpt","meaning":"摘錄","example":"The teacher read an excerpt from the travel diary.","example_zh":"老師朗讀了旅行日記的一段摘錄。","original_meaning":"摘錄","original_example":"An excerpt from the book.","original_example_zh":"書中的節選。"},{"source_id":873,"word":"exile","meaning":"流放；流亡","example":"The diary described the writer's years in exile.","example_zh":"日記描述作家流亡的歲月。","original_meaning":"流放","original_example":"He lived in exile.","original_example_zh":"他流亡異鄉。"},{"source_id":879,"word":"fabricate","meaning":"捏造","example":"The journalist refused to fabricate a story.","example_zh":"記者拒絕捏造報導。","original_meaning":"捏造","original_example":"He fabricated the story.","original_example_zh":"他捏造了這個故事。"},{"source_id":880,"word":"faction","meaning":"派系","example":"Each faction proposed a different plan for the city.","example_zh":"每個派系都提出不同的城市計畫。","original_meaning":"派系","original_example":"Political factions.","original_example_zh":"政治派系。"},{"source_id":885,"word":"foe","meaning":"敵人","example":"The story turned a former foe into a trusted friend.","example_zh":"故事讓昔日敵人成為可信賴的朋友。","original_meaning":"敵人","original_example":"The knight faced his old foe on the battlefield, ready for a decisive duel.","original_example_zh":"騎士在戰場上面對老對手，準備進行一場決定性的決鬥。"},{"source_id":888,"word":"forge","meaning":"鍛造；偽造","example":"The blacksmith used heat and a hammer to forge the iron.","example_zh":"鐵匠用熱和鐵鎚鍛造鐵。","original_meaning":"鍛造；偽造","original_example":"Forge a new path.","original_example_zh":"開闢新路。"},{"source_id":889,"word":"forthcoming","meaning":"即將來臨的","example":"The library announced a forthcoming exhibition of old maps.","example_zh":"圖書館宣布即將舉行古地圖展。","original_meaning":"即將來臨的","original_example":"The forthcoming election.","original_example_zh":"即將舉行的選舉。"},{"source_id":894,"word":"franchise","meaning":"加盟","example":"The family opened a café under a local franchise.","example_zh":"這家人加盟本地品牌，開了一間咖啡館。","original_meaning":"加盟","original_example":"A restaurant franchise.","original_example_zh":"一家餐廳加盟連鎖店。"},{"source_id":896,"word":"fruitful","meaning":"豐碩的","example":"The fruitful discussion produced several practical ideas.","example_zh":"富有成果的討論產生幾個實用想法。","original_meaning":"豐碩的","original_example":"A fruitful discussion.","original_example_zh":"一場富有成果的討論。"},{"source_id":898,"word":"futile","meaning":"徒勞的","example":"Their attempt to repair the badly torn paper was futile.","example_zh":"他們試圖修補嚴重撕裂的紙張，卻徒勞無功。","original_meaning":"徒勞的","original_example":"A futile attempt.","original_example_zh":"徒勞的嘗試。"},{"source_id":918,"word":"humiliate","meaning":"羞辱","example":"The coach chose to encourage the player rather than humiliate him.","example_zh":"教練選擇鼓勵球員，而非羞辱他。","original_meaning":"羞辱","original_example":"She was humiliated in public.","original_example_zh":"她在公眾面前受辱。"},{"source_id":919,"word":"hypothetical","meaning":"假設的","example":"The class tested a hypothetical plan using a model.","example_zh":"全班用模型測試一項假設的計畫。","original_meaning":"假設的","original_example":"A hypothetical scenario.","original_example_zh":"一個假設情境。"},{"source_id":921,"word":"ignite","meaning":"點燃","example":"The caretaker used a match to ignite the candle.","example_zh":"管理員用火柴點燃蠟燭。","original_meaning":"點燃","original_example":"to ignite iron or platinum","original_example_zh":"點燃鐵或鉑"},{"source_id":924,"word":"impair","meaning":"損害","example":"A scratched lens can impair the camera's image quality.","example_zh":"刮傷鏡片可能損害相機畫質。","original_meaning":"損害","original_example":"Alcohol impairs judgment.","original_example_zh":"酒精會影響判斷力。"},{"source_id":925,"word":"imperial","meaning":"帝國的","example":"The museum displayed an imperial carriage from the old kingdom.","example_zh":"博物館展示古王國的帝王馬車。","original_meaning":"帝國的","original_example":"The imperial palace.","original_example_zh":"皇宮。"},{"source_id":930,"word":"inclination","meaning":"傾向","example":"Her inclination to draw led her to join the art club.","example_zh":"她喜歡畫畫的傾向促使她加入美術社。","original_meaning":"傾向","original_example":"A natural inclination.","original_example_zh":"一種天生的傾向。"},{"source_id":932,"word":"indispensable","meaning":"不可或缺的","example":"The map became indispensable during the long journey.","example_zh":"這份地圖在長途旅程中變得不可或缺。","original_meaning":"不可或缺的","original_example":"Water is indispensable.","original_example_zh":"水是不可或缺的。"},{"source_id":941,"word":"innate","meaning":"天生的","example":"The scientist studied the bird's innate behavior.","example_zh":"科學家研究這種鳥的天生行為。","original_meaning":"天生的","original_example":"An innate ability.","original_example_zh":"與生俱來的能力。"},{"source_id":953,"word":"intricate","meaning":"複雜的","example":"The clock contained an intricate set of gears.","example_zh":"時鐘內有一組複雜精密的齒輪。","original_meaning":"複雜的","original_example":"An intricate design.","original_example_zh":"精巧的設計。"},{"source_id":954,"word":"intrinsic","meaning":"內在的","example":"The teacher emphasized the intrinsic value of learning.","example_zh":"老師強調學習本身的內在價值。","original_meaning":"內在的","original_example":"Intrinsic value.","original_example_zh":"內在價值。"},{"source_id":959,"word":"jeopardize","meaning":"危害","example":"Ignoring the crack could jeopardize the model's stability.","example_zh":"忽視裂縫可能危及模型穩定。","original_meaning":"危害","original_example":"Do not jeopardize your career.","original_example_zh":"不要危及你的職業生涯。"},{"source_id":960,"word":"jurisdiction","meaning":"管轄權","example":"The map showed the area under the council's jurisdiction.","example_zh":"地圖顯示議會管轄的區域。","original_meaning":"管轄權","original_example":"Under federal jurisdiction.","original_example_zh":"隸屬聯邦管轄。"},{"source_id":963,"word":"lament","meaning":"悲嘆","example":"The neighbors lamented the loss of the old oak tree.","example_zh":"鄰居為失去那棵老橡樹而惋惜。","original_meaning":"悲嘆","original_example":"He lamented his loss.","original_example_zh":"他為自己的損失感到惋惜。"},{"source_id":969,"word":"lure","meaning":"引誘","example":"The bright flowers can lure insects into the garden.","example_zh":"鮮豔花朵可以吸引昆蟲進入花園。","original_meaning":"引誘","original_example":"Lured by the offer.","original_example_zh":"被這項提議吸引。"},{"source_id":970,"word":"magnitude","meaning":"規模","example":"The model helped visitors understand the magnitude of the project.","example_zh":"模型幫助訪客了解工程的規模。","original_meaning":"規模","original_example":"The magnitude of the problem.","original_example_zh":"問題的嚴重性。"},{"source_id":5412,"word":"abode","meaning":"住所","example":"The cottage became their peaceful abode.","example_zh":"這間小屋成為他們寧靜的住所。","original_meaning":"住所","original_example":"A humble abode.","original_example_zh":"一間簡樸的住所。"},{"source_id":5416,"word":"admiral","meaning":"海軍上將","example":"The museum displayed a portrait of a retired admiral.","example_zh":"博物館展示一位退役海軍上將的肖像。","original_meaning":"海軍上將","original_example":"A navy admiral.","original_example_zh":"海軍上將。"},{"source_id":5432,"word":"clamp","meaning":"夾住","example":"The carpenter used a tool to clamp the wood in place.","example_zh":"木匠用工具把木材夾緊固定。","original_meaning":"夾住","original_example":"Clamp down on fraud.","original_example_zh":"嚴打詐欺。"},{"source_id":5472,"word":"limestone","meaning":"石灰岩","example":"The guide pointed out the limestone layers in the cliff.","example_zh":"導覽員指出峭壁中的石灰岩層。","original_meaning":"石灰岩","original_example":"A limestone cliff.","original_example_zh":"石灰岩懸崖。"},{"source_id":5477,"word":"lumber","meaning":"木材","example":"The workers stacked the lumber in a dry shed.","example_zh":"工人把木材堆放在乾燥棚屋。","original_meaning":"木材","original_example":"A lumber yard.","original_example_zh":"木材場。"},{"source_id":5518,"word":"elation","meaning":"興高采烈","example":"The team felt elation when its bridge model passed the test.","example_zh":"橋梁模型通過測試時，團隊欣喜萬分。","original_meaning":"興高采烈","original_example":"A feeling of elation.","original_example_zh":"一種欣喜若狂的感覺。"},{"source_id":5521,"word":"melancholy","meaning":"憂鬱","example":"The quiet music filled the room with melancholy.","example_zh":"靜謐音樂讓房間充滿淡淡憂鬱。","original_meaning":"憂鬱","original_example":"A deep melancholy.","original_example_zh":"深沉的憂鬱。"},{"source_id":5541,"word":"consul","meaning":"領事","example":"The consul helped the travelers contact their families.","example_zh":"領事協助旅人聯絡家人。","original_meaning":"領事","original_example":"The US consul.","original_example_zh":"美國領事。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 38 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-entity-01-v1","level":"senior","word":"entity","sort_order":1,"sense":"實體","alt_zh":"成年管理人員在桌上把博物館建築模型與其他機構模型分開，討論組織。","example":"The museum became a separate entity after the reorganization.","example_zh":"改組後，博物館成為獨立實體。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/entity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-envision-01-v1","level":"senior","word":"envision","sort_order":1,"sense":"預想","alt_zh":"學生在教室桌面規畫充滿樹木與花園的校園模型。","example":"The students tried to envision a greener school.","example_zh":"學生試著想像更綠化的校園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/envision-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-equity-01-v1","level":"senior","word":"equity","sort_order":1,"sense":"公平","alt_zh":"成年委員和教師在桌上按各組不同需要分配教材，友善討論。","example":"The committee considered equity when distributing the resources.","example_zh":"委員會分配資源時考量公平。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/equity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-erratic-01-v1","level":"senior","word":"erratic","sort_order":1,"sense":"不穩定的","alt_zh":"科學桌上玩具車沿彎曲不規則路線移動，學生觀察。","example":"The toy car's erratic movement made it hard to follow.","example_zh":"玩具車不穩定的移動讓人難以追蹤。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/erratic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-evade-01-v1","level":"senior","word":"evade","sort_order":1,"sense":"逃避","alt_zh":"成年演講者在公開問答會面露猶豫轉看其他資料，提問者等待。","example":"The speaker tried to evade the difficult question.","example_zh":"演講者試圖迴避這個困難問題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/evade-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-excerpt-01-v1","level":"senior","word":"excerpt","sort_order":1,"sense":"摘錄","alt_zh":"成年教師在教室拿著旅行日記朗讀，桌上展開一頁選文與風景圖。","example":"The teacher read an excerpt from the travel diary.","example_zh":"老師朗讀了旅行日記的一段摘錄。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/excerpt-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-exile-01-v1","level":"senior","word":"exile","sort_order":1,"sense":"流放；流亡","alt_zh":"成年歷史研究者在圖書館看老日記，旁有插圖呈現成年作家在異鄉書桌寫作。","example":"The diary described the writer's years in exile.","example_zh":"日記描述作家流亡的歲月。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/exile-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fabricate-01-v1","level":"senior","word":"fabricate","sort_order":1,"sense":"捏造","alt_zh":"成年記者在書桌前把沒有證據的草稿移開，專心查看真實採訪筆記。","example":"The journalist refused to fabricate a story.","example_zh":"記者拒絕捏造報導。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fabricate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-faction-01-v1","level":"senior","word":"faction","sort_order":1,"sense":"派系","alt_zh":"虛構市政會議兩組成年代表各自展示不同城市模型，平靜討論。","example":"Each faction proposed a different plan for the city.","example_zh":"每個派系都提出不同的城市計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/faction-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-foe-01-v1","level":"senior","word":"foe","sort_order":1,"sense":"敵人","alt_zh":"舞台故事兩位穿完整旅行衣的成年角色在堅固橋上友善握手，無武器。","example":"The story turned a former foe into a trusted friend.","example_zh":"故事讓昔日敵人成為可信賴的朋友。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/foe-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-forge-01-v1","level":"senior","word":"forge","sort_order":1,"sense":"鍛造；偽造","alt_zh":"成年鐵匠穿完整防護衣在安全工坊用錘鍛造小鐵環，無武器製作。","example":"The blacksmith used heat and a hammer to forge the iron.","example_zh":"鐵匠用熱和鐵鎚鍛造鐵。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/forge-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-forthcoming-01-v1","level":"senior","word":"forthcoming","sort_order":1,"sense":"即將來臨的","alt_zh":"成年館員在尚未開放的展區布置老地圖，成年訪客在外期待。","example":"The library announced a forthcoming exhibition of old maps.","example_zh":"圖書館宣布即將舉行古地圖展。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/forthcoming-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-franchise-01-v1","level":"senior","word":"franchise","sort_order":1,"sense":"加盟","alt_zh":"成年家人在新咖啡館迎客，櫃台設計與桌上另一分店照片相似，無品牌文字。","example":"The family opened a café under a local franchise.","example_zh":"這家人加盟本地品牌，開了一間咖啡館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/franchise-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fruitful-01-v1","level":"senior","word":"fruitful","sort_order":1,"sense":"豐碩的","alt_zh":"學生圍桌微笑看多個完成的設計草圖與小模型。","example":"The fruitful discussion produced several practical ideas.","example_zh":"富有成果的討論產生幾個實用想法。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fruitful-01-v1.webp","local_path":"","style":"g